    "description": "Meltingly tender bone-in short ribs braised low and slow in a full-bodied red wine and tomato sauce, finished with sweet young carrots and a bright citrus-herb gremolata. Pure cold-weather comfort that practically falls off the bone. Recipe from Bon Appétit: https://www.bonappetit.com/recipe/red-wine-braised-short-ribs-with-carrots",
