    "description": "A rustic free-form tart of thinly sliced apples glazed in vanilla brown butter and muscovado sugar, baked in a golden, flaky crust and served with billowy maple whipped cream. Cozy, buttery, and deceptively simple. Recipe from Bon Appétit: https://www.bonappetit.com/recipe/salted-butter-apple-galette-with-maple-whipped-cream",
