    "name": "Perfect Soft-boiled Eggs",
    "description": "Jammy, golden-centered soft-boiled eggs with a tender white, served with crisp buttered toast soldiers for dipping. A foolproof 6-minute breakfast that nails the runny yolk every time. Recipe from Simple Home Edit: https://simplehomeedit.com/recipe/perfect-soft-boiled-eggs/",
